  "labels": [
    {
      "label": "M_Gambling",
      "span": "why would I ever come back and spend more money when it is impossible to when",
      "rule_applied": "Loot Boxes / Gambling: spending real money to play a game of chance for a reward",
      "rationale": "The game is identified as casino slots, and this span links spending more money with attempting to win a chance-based reward."
